7	/** Identifies a plan revision in `~/.symbiot/agents/{agentId}/history/{project}/{slug}/00N.md`. */
8	export interface PlanMeta {
9	  project: string;
10	  slug: string;
11	  version: number;
12	  /**
13	   * Human-readable label rendered in the viewer's top bar. Resolved from git
14	   * context as `<repo> · <branch>` (or just `<repo>` on detached HEAD), with
15	   * `basename(cwd)` as a fallback when git is unavailable. Decoupled from
16	   * `project` so the on-disk slug stays stable across worktrees.
17	   */
18	  displayName: string;
19	}
20	
21	/** Operating mode of the viewer. `plan` = Approve/Deny; `annotate` = Submit feedback. */
22	export type ViewerMode = "plan" | "annotate";
23	
24	/** Response payload of `GET /api/plan`. */
25	export interface PlanResponse {
26	  plan: string;
27	  mode: ViewerMode;
28	  meta: PlanMeta;
29	}
