2	 * Pinned snapshot of `@symbiot/viewer`'s public, agent-facing contract.
3	 *
4	 * This is the cross-workspace surface that `@symbiot/agent-runtime`
5	 * (`packages/symbiot-agent-runtime/src/runPlanReview.ts`) and
6	 * `apps/opencode-plugin` consume. The companion {@link ./surface.assert.ts}
7	 * compares the live types in `../startServer.ts` (and `../routes.ts`) against
8	 * the baseline below; any divergence fails
9	 * `bun run --filter @symbiot/viewer typecheck`, forcing a contract change to be
10	 * acknowledged in the same PR.
11	 *
12	 * The shapes are inlined (not re-imported from live source) on purpose — a
13	 * snapshot that referenced the live `PlanMeta`/`ViewerMode` would move together
14	 * with them and never detect drift. Nested shapes are pinned here too.
15	 *
16	 * To regenerate after an intentional change: copy the live definitions into the
17	 * matching declarations below, then re-run typecheck.
18	 */
19	
20	/** Mirrors `ViewerMode` in `../../shared/apiTypes.ts`. */
21	export type ViewerModeSnapshot = "plan" | "annotate";
22	
23	/** Mirrors `PlanMeta` in `../../shared/apiTypes.ts`. */
