1	import { readFile } from "node:fs/promises";
2	
3	import type { ViewerMode } from "./shared/apiTypes.ts";
4	import { startServer, type RunningServer } from "./server/startServer.ts";
5	
6	interface CliArgs {
7	  planPath: string | null;
8	  noOpen: boolean;
9	  keepAlive: boolean;
10	  decisionFile: string | null;
11	  port: number | null;
12	  mode: ViewerMode;
13	}
14	
15	const flagValue = (argv: string[], flag: string): string | null => {
16	  const idx = argv.indexOf(flag);
17	  return idx >= 0 ? (argv[idx + 1] ?? null) : null;
18	};
19	
20	const parsePort = (raw: string | null): number | null => {
21	  if (raw === null) return null;
22	  const n = Number.parseInt(raw, 10);
23	  return Number.isFinite(n) && n > 0 ? n : null;
24	};
25	
26	const parseMode = (raw: string | null): ViewerMode => (raw === "annotate" ? "annotate" : "plan");
27	
28	const parseArgs = (argv: string[]): CliArgs => ({
29	  planPath: flagValue(argv, "--plan"),
30	  noOpen: argv.includes("--no-open"),
31	  keepAlive: argv.includes("--keep-alive"),
32	  decisionFile: flagValue(argv, "--decision-file"),
33	  port: parsePort(flagValue(argv, "--port")),
34	  mode: parseMode(flagValue(argv, "--mode")),
35	});
36	
37	const readStdin = async (): Promise<string> => {
38	  const chunks: Uint8Array[] = [];
39	  for await (const chunk of process.stdin) chunks.push(chunk as Uint8Array);
40	  return Buffer.concat(chunks).toString("utf8");
41	};
42	
43	const readPlan = async (planPath: string | null): Promise<string> => {
44	  if (planPath !== null) return readFile(planPath, "utf8");
45	  if (process.stdin.isTTY) throw new Error("Pass --plan <file> or pipe markdown on stdin.");
46	  return readStdin();
47	};
48	
49	const printDecision = (
50	  decision:
51	    | { kind: "approve" }
52	    | { kind: "deny"; feedback: string }
53	    | { kind: "feedback"; feedback: string }
54	): void => {
55	  if (decision.kind === "approve") {
56	    process.stdout.write("APPROVED\n");
57	    return;
58	  }
59	  if (decision.kind === "feedback") {
60	    process.stdout.write(`${decision.feedback}\n`);
61	    return;
62	  }
63	  process.stdout.write(`DENIED\n${decision.feedback}\n`);
64	};
65	
66	const exitCodeFor = (kind: "approve" | "deny" | "feedback"): number => {
67	  if (kind === "approve") return 0;
68	  if (kind === "feedback") return 0;
69	  return 2;
70	};
71	
72	const runOneShot = async (server: RunningServer): Promise<void> => {
73	  const decision = await server.resolved;
74	  await server.stop();
75	  printDecision(decision);
76	  process.exit(exitCodeFor(decision.kind));
77	};
78	
79	const runKeepAlive = (server: RunningServer): void => {
80	  const shutdown = async (): Promise<void> => {
81	    await server.stop();
82	    process.exit(0);
83	  };
84	  process.on("SIGINT", () => void shutdown());
85	  process.on("SIGTERM", () => void shutdown());
86	};
87	
88	const main = async (): Promise<void> => {
89	  const args = parseArgs(process.argv.slice(2));
90	  const plan = await readPlan(args.planPath);
91	  const server = await startServer({
92	    plan,
93	    openInBrowser: !args.noOpen,
94	    decisionFile: args.decisionFile,
95	    port: args.port,
96	    mode: args.mode,
97	  });
98	  process.stdout.write(`symbiot viewer listening at ${server.url}\n`);
99	  if (args.keepAlive) {
100	    runKeepAlive(server);
101	    return;
102	  }
103	  await runOneShot(server);
104	};
105	
106	main().catch((error: unknown) => {
107	  const message = error instanceof Error ? error.message : String(error);
108	  process.stderr.write(`${message}\n`);
109	  process.exit(1);
110	});
