1	/**
2	 * Client-side wrapper for `/api/*`. Dispatches through {@link apiRoutes} so no
3	 * route path or method appears as a string here. Responses are validated with
4	 * Zod at the boundary; the rest of the app deals with trusted shapes.
5	 */
6	import { z } from "zod";
7	
8	import { apiRoutes, type ApiRouteId } from "../../shared/apiRoutes.ts";
9	import type {
10	  DraftPayload,
11	  PlanResponse,
12	  PlanVersionResponse,
13	  PlanVersionsResponse,
14	} from "../../shared/apiTypes.ts";
15	
16	const planMetaSchema = z.object({
17	  project: z.string(),
18	  slug: z.string(),
19	  version: z.number().int(),
20	  displayName: z.string(),
21	});
22	
23	const planResponseSchema = z.object({
24	  plan: z.string(),
25	  mode: z.enum(["plan", "annotate"]),
26	  meta: planMetaSchema,
27	}) satisfies z.ZodType<PlanResponse>;
28	
29	const planVersionsResponseSchema = z.object({
30	  versions: z.array(z.number().int()),
31	  current: z.number().int(),
32	}) satisfies z.ZodType<PlanVersionsResponse>;
33	
34	const planVersionResponseSchema = z.object({
35	  plan: z.string(),
36	  meta: planMetaSchema,
37	}) satisfies z.ZodType<PlanVersionResponse>;
38	
39	const globalCommentSchema = z.object({
40	  id: z.string(),
41	  body: z.string(),
42	  images: z.array(z.string()).optional(),
43	});
44	
45	const draftPayloadSchema = z.object({
46	  value: z.array(z.unknown()),
47	  commentBodies: z.record(z.string(), z.string()),
48	  commentImages: z.record(z.string(), z.array(z.string())).optional(),
49	  commentOriginalTexts: z.record(z.string(), z.string()).optional(),
50	  suggestionOriginalTexts: z.record(z.string(), z.string()).optional(),
51	  globalComments: z.array(globalCommentSchema),
52	  updatedAt: z.number(),
53	}) satisfies z.ZodType<DraftPayload>;
54	
55	interface RequestOptions<T> {
56	  /** Zod schema to parse the response with. `null` means: ignore the body. */
57	  schema: z.ZodType<T> | null;
58	  body?: unknown;
59	  query?: Record<string, string>;
60	}
61	
62	const buildUrl = (path: string, query?: Record<string, string>): string => {
63	  if (query === undefined) return path;
64	  const params = new URLSearchParams(query);
65	  const qs = params.toString();
66	  return qs.length > 0 ? `${path}?${qs}` : path;
67	};
68	
69	const request = async <T>(id: ApiRouteId, opts: RequestOptions<T>): Promise<T> => {
70	  const { method, path } = apiRoutes[id];
71	  const init: RequestInit = { method };
72	  if (opts.body !== undefined) {
73	    init.headers = { "Content-Type": "application/json" };
74	    init.body = JSON.stringify(opts.body);
75	  }
76	  const res = await fetch(buildUrl(path, opts.query), init);
77	  if (!res.ok) throw new Error(`${method} ${path} failed: ${res.status}`);
78	  if (opts.schema === null) return undefined as T;
79	  // 204 No Content is a valid "absent" signal for nullable schemas (e.g. draft).
80	  if (res.status === 204) return opts.schema.parse(null);
81	  return opts.schema.parse(await res.json());
82	};
83	
84	/** Fetch the plan + viewer mode for the current session. */
85	export const fetchPlan = (): Promise<PlanResponse> =>
86	  request("plan", { schema: planResponseSchema });
87	
88	/** List every plan version persisted on disk, plus the version currently in session. */
89	export const fetchPlanVersions = (): Promise<PlanVersionsResponse> =>
90	  request("planVersions", { schema: planVersionsResponseSchema });
91	
92	/** Load a specific plan version's markdown by version number. */
93	export const fetchPlanVersion = (version: number): Promise<PlanVersionResponse> =>
94	  request("planVersion", {
95	    schema: planVersionResponseSchema,
96	    query: { n: String(version) },
97	  });
98	
99	/** Approve the plan. Server records the decision and shuts down. */
100	export const postApprove = (): Promise<void> => request("approve", { schema: null });
101	
102	/** Deny the plan (plan mode). Reviewer's free-text feedback travels in the body. */
103	export const postDeny = (feedback: string): Promise<void> =>
104	  request("deny", { schema: null, body: { feedback } });
105	
106	/** Submit serialized annotation feedback (annotate mode). */
107	export const postFeedback = (feedback: string): Promise<void> =>
108	  request("feedback", { schema: null, body: { feedback } });
109	
110	/** Load the persisted draft for this plan, or null when no draft exists. */
111	export const getDraft = (): Promise<DraftPayload | null> =>
112	  request("draftGet", { schema: draftPayloadSchema.nullable() });
113	
114	/** Persist the draft for this plan. Debounced by the caller. */
115	export const putDraft = (draft: DraftPayload): Promise<void> =>
116	  request("draftPut", { schema: null, body: draft });
117	
118	/** Remove the persisted draft for this plan. Idempotent on the server. */
119	export const deleteDraft = (): Promise<void> => request("draftDelete", { schema: null });
120

