6	import { SymbiotDiffKit } from "../utils/kit.ts";
7	import { computeDiffValue, hasAnyDiff, pickChangedBlocks } from "../utils/diffPlugin.ts";
8	
9	/** Visible diff view mode. `clean` drops untouched top-level blocks; `raw` keeps everything. */
10	export type DiffMode = "clean" | "raw";
11	
12	interface DiffEditorProps {
13	  /** Markdown of the version selected in the History tab. */
14	  current: string;
15	  /** Markdown of the version immediately preceding `current`. */
16	  previous: string;
17	  /** Diff filter mode. `clean` (default in callers) drops unchanged blocks. */
18	  mode: DiffMode;
19	}
20	
21	interface DiffBuild {
22	  /** Full diff value (every block from `current` with diff annotations). */
23	  full: PlateValue;
24	  /** Value to actually render given `mode` — `full` for Raw, filtered for Clean. */
25	  rendered: PlateValue;
26	  /** True when at least one block carries a diff operation. */
27	  hasChanges: boolean;
28	}
29	
30	const buildDiff = (previous: string, current: string, mode: DiffMode): DiffBuild => {
31	  const editor = createPlateEditor({ plugins: SymbiotDiffKit });
32	  const md = editor.getApi(MarkdownPlugin).markdown;
33	  const prevValue = md.deserialize(previous) as PlateValue;
34	  const currValue = md.deserialize(current) as PlateValue;
35	  const full = computeDiffValue(prevValue, currValue, editor);
36	  const hasChanges = hasAnyDiff(full);
37	  const rendered = mode === "clean" ? pickChangedBlocks(full) : full;
38	  return { full, rendered, hasChanges };
39	};
40	
41	/**
42	 * Read-only Plate editor that renders the inline diff between two markdown
43	 * versions. The transient `createPlateEditor` builds the diff value off the
44	 * render path; the live `usePlateEditor` renders that value through the same
45	 * `SymbiotDiffKit` so prose styling (tables, code blocks, lists) matches the
46	 * editable `ReviewEditor`. Re-keyed by `mode` so toggling Clean / Raw rebuilds
47	 * the editor state cleanly. When the two versions are byte-identical the diff
48	 * is empty — surface that explicitly so the reviewer isn't staring at a blank
49	 * pane wondering whether the renderer broke.
50	 */
51	export const DiffEditor = ({ current, previous, mode }: DiffEditorProps): React.ReactElement => {
52	  const diff = useMemo(() => buildDiff(previous, current, mode), [previous, current, mode]);
53	  // No deps on `usePlateEditor`: the parent (`DiffMount`) re-keys this
54	  // component on `mode` change, so the editor is freshly constructed with
55	  // the correct value baked in on every mount.
56	  const editor = usePlateEditor({
57	    plugins: SymbiotDiffKit,
58	    value: diff.rendered as never,
59	  });
60	  return (
61	    <div
62	      data-testid="diff-editor-root"
63	      data-diff-mode={mode}
64	      data-diff-empty={!diff.hasChanges}
65	      className="prose prose-neutral dark:prose-invert relative mx-auto max-w-3xl"
66	    >
67	      {!diff.hasChanges && (
68	        <p
69	          data-testid="diff-editor-empty"
70	          className="text-muted-foreground border-border bg-muted/40 not-prose mb-4 rounded-md border px-4 py-3 text-sm"
71	        >
72	          No textual differences between this version and its predecessor.
73	        </p>
74	      )}
75	      <Plate editor={editor}>
76	        <PlateContent readOnly className="outline-none" />
77	      </Plate>
78	    </div>
79	  );
80	};
