import { MarkdownPlugin } from "@platejs/markdown";
import { useCallback, useEffect } from "react";
import { Plate, PlateContent, usePlateEditor } from "platejs/react";

import { SymbiotDraftKit } from "../utils/kit.ts";

/**
 * Imperative handle exposed by {@link DraftEditor} once Plate is constructed.
 * The host pulls markdown lazily (autosave, Send to agent, Approve) instead of
 * paying serialization on every keystroke.
 */
export interface DraftEditorHandle {
  /** Serialize the current Plate value back to markdown. */
  getMarkdown: () => string;
}

/** Props accepted by {@link DraftEditor}. */
interface DraftEditorProps {
  /** Markdown the draft session boots from (seed file or blank template). */
  markdown: string;
  /** Receives the imperative handle once Plate is constructed. */
  onReady?: (handle: DraftEditorHandle) => void;
  /** Fires on every Plate editor change; pull markdown via the handle when needed. */
  onChange?: () => void;
}

/**
 * Editable Plate editor for the `draft` viewer mode — the author writes plan
 * markdown as free text. Unlike {@link ReviewEditor} there is no `readOnly`
 * and no typing guard: the document body itself is the editing surface, and
 * annotation marks never apply here ({@link SymbiotDraftKit} carries only the
 * shared markdown surface). `getMarkdown()` runs the markdown round-trip in
 * reverse (`editor.api.markdown.serialize`), pinned deterministic and lossless
 * by `utils/markdownRoundTrip.test.ts` (NFR-4).
 *
 * @example
 * ```tsx
 * <DraftEditor
 *   markdown={plan}
 *   onReady={(handle) => { handleRef.current = handle; }}
 *   onChange={scheduleAutosave}
 * />
 * ```
 */
export const DraftEditor = ({
  markdown,
  onReady,
  onChange,
}: DraftEditorProps): React.ReactElement => {
  const editor = usePlateEditor({
    plugins: SymbiotDraftKit,
    value: (e): never => e.getApi(MarkdownPlugin).markdown.deserialize(markdown) as never,
  });

  useEffect(() => {
    onReady?.({ getMarkdown: () => editor.getApi(MarkdownPlugin).markdown.serialize() });
  }, [editor, onReady]);

  const handleChange = useCallback(() => onChange?.(), [onChange]);

  return (
    <div
      data-testid="draft-editor-root"
      className="prose prose-neutral dark:prose-invert relative mx-auto max-w-3xl"
    >
      <Plate editor={editor} onChange={handleChange}>
        <PlateContent className="outline-none" />
      </Plate>
    </div>
  );
};

// @vitest-environment happy-dom
import { MarkdownPlugin } from "@platejs/markdown";
import { render } from "@testing-library/react";
import { createSlateEditor } from "platejs";
import { describe, expect, it, vi } from "vitest";

import { SymbiotDraftKit } from "../utils/kit.ts";

import { DraftEditor, type DraftEditorHandle } from "./DraftEditor.tsx";

const seed = "# Feature plan\n\nAdd the thing.\n";

describe("draft value pipeline (headless)", () => {
  it("editing the value changes what serializes back to markdown", () => {
    const editor = createSlateEditor({ plugins: SymbiotDraftKit });
    const md = editor.getApi(MarkdownPlugin).markdown;
    editor.children = md.deserialize(seed);
    editor.tf.insertText("Revised: ", { at: { path: [1, 0], offset: 0 } });
    const serialized = md.serialize();
    expect(serialized).toContain("Revised: Add the thing.");
    expect(serialized).toContain("# Feature plan");
  });
});

describe("DraftEditor component", () => {
  it("renders an editable surface and exposes a markdown round-trip handle", () => {
    let handle: DraftEditorHandle | null = null;
    const onReady = vi.fn((h: DraftEditorHandle) => {
      handle = h;
    });
    const { container } = render(<DraftEditor markdown={seed} onReady={onReady} />);

    expect(container.querySelector('[data-testid="draft-editor-root"]')).not.toBeNull();
    // Editable: PlateContent must NOT render contenteditable=false (draft mode types directly).
    const editable = container.querySelector("[contenteditable]");
    expect(editable?.getAttribute("contenteditable")).toBe("true");

    expect(onReady).toHaveBeenCalledTimes(1);
    if (handle === null) throw new Error("onReady did not deliver a handle");
    const roundTripped = (handle as DraftEditorHandle).getMarkdown();
    expect(roundTripped).toContain("# Feature plan");
    expect(roundTripped).toContain("Add the thing.");
  });
});

/**
 * NFR-4 gate for the draft mode's serialize-back path: markdown → Plate →
 * markdown must be semantically lossless, deterministic, and invisible to the
 * version diff.
 *
 * Canonical form: the first `serialize` pass MAY re-normalize byte-level
 * syntax the parser treats as equivalent (emphasis markers, list bullets,
 * fence style, wrapping). That normalized output is the canonical form — the
 * idempotency assertion pins that a second pass is byte-stable, and the
 * diff-cleanliness assertion pins that normalization can never surface as
 * phantom changes in the revision diff (the diff compares deserialized Plate
 * values, not markdown bytes).
 */
import { readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { MarkdownPlugin } from "@platejs/markdown";
import { createSlateEditor } from "platejs";
import { describe, expect, it } from "vitest";
import type { PlateValue } from "@symbiot/annotations";

import { computeDiffValue, hasAnyDiff } from "./diffPlugin.ts";
import { SymbiotDiffKit, SymbiotDraftKit } from "./kit.ts";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..", "..");

/**
 * Every element class the viewer supports (elements.md) plus the golden
 * feedback bodies — tables, nested lists, task lists, code fences, quotes.
 */
const corpus = [
  "fixtures/markdown/elements.md",
  "fixtures/markdown/elements-revised.md",
  "fixtures/markdown/no-heading.md",
  "fixtures/golden/comment.md",
  "fixtures/golden/global-comment.md",
  "fixtures/golden/deletion.md",
  "fixtures/golden/insertion.md",
  "fixtures/golden/replacement.md",
  "fixtures/golden/mixed.md",
  "fixtures/golden/task.md",
];

const draftMd = createSlateEditor({ plugins: SymbiotDraftKit }).getApi(MarkdownPlugin).markdown;

describe.each(corpus)("markdown round-trip: %s", (fixture) => {
  const load = (): Promise<string> => readFile(join(repoRoot, fixture), "utf8");

  it("is semantically lossless (deserialize ∘ serialize is identity on Plate values)", async () => {
    const source = await load();
    const value = draftMd.deserialize(source);
    const serialized = draftMd.serialize({ value });
    expect(draftMd.deserialize(serialized)).toEqual(value);
  });

  it("serialize is idempotent (second pass is byte-stable)", async () => {
    const source = await load();
    const canonical = draftMd.serialize({ value: draftMd.deserialize(source) });
    const secondPass = draftMd.serialize({ value: draftMd.deserialize(canonical) });
    expect(secondPass).toBe(canonical);
  });

  it("normalization never surfaces in the version diff (zero diff ops)", async () => {
    const source = await load();
    const diffEditor = createSlateEditor({ plugins: SymbiotDiffKit });
    const md = diffEditor.getApi(MarkdownPlugin).markdown;
    const original = md.deserialize(source) as PlateValue;
    const roundTripped = md.deserialize(draftMd.serialize({ value: original })) as PlateValue;
    const diff = computeDiffValue(original, roundTripped, diffEditor);
    expect(hasAnyDiff(diff)).toBe(false);
  });
});

