36	  startServer?: RunPlanReviewOptions["startServer"];
37	}
38	
39	/**
40	 * Boot the viewer in annotate mode against `filePath`. Exits 0 on submitted
41	 * feedback (printed to stdout), 1 on a non-feedback resolution, 64 on a missing
42	 * path.
43	 */
44	export const runAnnotate = async ({
45	  filePath,
46	  binName,
47	  agentId,
48	  indexHtmlGz,
49	  startServer,
50	}: RunAnnotateOptions): Promise<number> => {
51	  if (filePath === undefined) {
52	    process.stderr.write(`usage: ${binName} annotate <file.md>\n`);
53	    return 64;
54	  }
55	  const plan = await readFile(filePath, "utf8");
56	  return runPlanReview({
57	    plan,
58	    mode: "annotate",
59	    serverOptions: { indexHtmlGz, agentId },
60	    startServer,
61	    onStart: (url) => process.stderr.write(`${binName}: annotate ${filePath} at ${url}\n`),
62	    onResolved: (decision) => {
63	      if (decision.kind === "feedback") {
64	        process.stdout.write(`${decision.feedback}\n`);
65	        return 0;
66	      }
67	      return 1;
68	    },
69	  });
70	};
