1	/**
2	 * Shared spawn-and-decide loop for agent integrations.
3	 *
4	 * Every agent (Claude Code today; Codex/Gemini/Copilot/OpenCode next) drives the
5	 * same sequence to review a plan: spawn the {@link @symbiot/viewer} server, hand
6	 * the reviewer a URL, block until they decide, tear the server down, then map the
7	 * decision to a process exit code. {@link runPlanReview} owns that loop so each
8	 * agent only supplies the parts that genuinely differ — how it parses stdin and
9	 * how it emits its own decision shape — via the {@link RunPlanReviewOptions.onResolved}
10	 * callback. `@symbiot/viewer` (`startServer` / `RunningServer`) stays the boundary.
11	 *
12	 * @example
13	 * ```ts
14	 * import { runPlanReview } from "@symbiot/agent-runtime";
15	 *
16	 * const exitCode = await runPlanReview({
17	 *   plan,
18	 *   onStart: (url) => process.stderr.write(`review at ${url}\n`),
19	 *   onResolved: (decision) => (decision.kind === "approve" ? 0 : 2),
20	 * });
21	 * process.exit(exitCode);
22	 * ```
23	 */
24	import {
25	  startServer as defaultStartServer,
26	  type RunningServer,
27	  type StartServerOptions,
28	} from "@symbiot/viewer";
29	
30	/**
31	 * The reviewer's decision, derived from the viewer boundary so this package
32	 * does not need its own copy of the `Decision` union (and the viewer stays
33	 * untouched). Resolves to `approve` / `deny` / `feedback`.
34	 */
35	type ReviewDecision = Awaited<RunningServer["resolved"]>;
36	
37	/** Options for {@link runPlanReview}. */
38	export interface RunPlanReviewOptions {
39	  /** Plan or document markdown to review. */
40	  plan: string;
41	  /** Viewer mode: `plan` (Approve/Deny) or `annotate` (Submit feedback). Defaults to the viewer's own default (`plan`). */
42	  mode?: StartServerOptions["mode"];
43	  /** Extra viewer options (e.g. `indexHtmlGz`, `port`, `decisionFile`) forwarded to `startServer`. `plan` and `mode` are passed separately. */
44	  serverOptions?: Omit<StartServerOptions, "plan" | "mode">;
45	  /** Called once with the viewer URL right after the server boots — agents use it to print their own stderr line. Optional. */
46	  onStart?: (url: string) => void;
47	  /** Maps the reviewer's decision to the process exit code. The returned value becomes {@link runPlanReview}'s resolved value; agents emit their decision JSON here. */
48	  onResolved: (decision: ReviewDecision) => number | Promise<number>;
49	  /** Injection seam for tests; defaults to the real `@symbiot/viewer` `startServer`. Production callers omit it. */
50	  startServer?: typeof defaultStartServer;
51	}
52	
53	/**
54	 * Run the spawn → await → decide loop and resolve to the exit code returned by
55	 * {@link RunPlanReviewOptions.onResolved}.
56	 *
57	 * `server.resolved` only ever resolves (it is wired from the viewer's POST
58	 * handler, never rejected), so teardown needs no `try`/`finally`.
59	 */
60	export const runPlanReview = async ({
61	  plan,
62	  mode,
63	  serverOptions,
64	  onStart,
65	  onResolved,
66	  startServer = defaultStartServer,
67	}: RunPlanReviewOptions): Promise<number> => {
68	  const server = await startServer({ plan, mode, ...serverOptions });
69	  onStart?.(server.url);
70	  const decision = await server.resolved;
71	  await server.stop();
72	  return onResolved(decision);
73	};
