49	const errorMessage = (error: unknown): string =>
50	  error instanceof Error ? error.message : String(error);
51	
52	const recordDecision = async (path: string, decision: Decision): Promise<void> => {
53	  const payload = JSON.stringify({ ...decision, at: Date.now() });
54	  await writeFile(path, payload, "utf8");
55	};
56	
57	const jsonResponse = (body: unknown, status = 200): Response =>
58	  new Response(JSON.stringify(body), {
59	    status,
60	    headers: { "Content-Type": "application/json; charset=utf-8" },
61	  });
62	
63	const planRoute = (ctx: RouteContext): Response =>
64	  jsonResponse({ plan: ctx.plan, mode: ctx.mode, meta: ctx.meta });
65	
66	const planVersionsRoute = async (ctx: RouteContext): Promise<Response> => {
67	  const versions = await listVersions(ctx.agentId, ctx.meta);
68	  return jsonResponse({ versions, current: ctx.meta.version });
69	};
70	
71	const versionParamPattern = /^[1-9]\d*$/;
72	
73	const parseVersionParam = (raw: string | null): number | null => {
74	  if (raw === null || !versionParamPattern.test(raw)) return null;
75	  return Number.parseInt(raw, 10);
76	};
77	
78	const parseVersionNumber = (value: unknown): number | null => {
79	  if (typeof value !== "number" || !Number.isInteger(value) || value < 1) return null;
80	  return value;
81	};
82	
83	const planVersionRoute = async (req: Request, ctx: RouteContext): Promise<Response> => {
84	  const url = new URL(req.url);
85	  const n = parseVersionParam(url.searchParams.get("n"));
86	  if (n === null) return badRequest("invalid version");
87	  try {
88	    const meta = { ...ctx.meta, version: n };
89	    const plan = await loadPlan(ctx.agentId, meta);
90	    return jsonResponse({ plan, meta });
91	  } catch (error) {
92	    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
93	      return new Response("Not Found", { status: 404 });
94	    }
95	    throw error;
96	  }
97	};
