99	/**
100	 * Spawn `code --diff <from> <to>` against two persisted versions. Plannotator-
101	 * compatible endpoint for VS Code / Obsidian integrations. Detached + unref so
102	 * the viewer process stays independent of the external editor's lifetime.
103	 *
104	 * Response codes:
105	 * - 204 — spawn issued, VS Code is opening the diff
106	 * - 400 — invalid body or unknown version numbers
107	 * - 404 — at least one of the requested version files is missing on disk
108	 * - 503 — `code` is not installed on PATH; body `{ reason: "code-cli-missing" }`
109	 */
110	interface VscodeDiffInput {
111	  from: number;
112	  to: number;
113	}
114	
115	const parseVscodeDiffBody = async (req: Request): Promise<VscodeDiffInput | null> => {
116	  const body = (await req.json().catch(() => null)) as { from?: unknown; to?: unknown } | null;
117	  if (body === null) return null;
118	  const from = parseVersionNumber(body.from);
119	  const to = parseVersionNumber(body.to);
120	  if (from === null || to === null) return null;
121	  return { from, to };
122	};
123	
124	const assertVersionsExist = async (
125	  ctx: RouteContext,
126	  input: VscodeDiffInput
127	): Promise<Response | null> => {
128	  try {
129	    await Promise.all([
130	      loadPlan(ctx.agentId, { ...ctx.meta, version: input.from }),
131	      loadPlan(ctx.agentId, { ...ctx.meta, version: input.to }),
132	    ]);
133	    return null;
134	  } catch (error) {
135	    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
136	      return new Response("Not Found", { status: 404 });
137	    }
138	    throw error;
139	  }
140	};
141	
142	const planVscodeDiffRoute = async (req: Request, ctx: RouteContext): Promise<Response> => {
143	  const input = await parseVscodeDiffBody(req);
144	  if (input === null) return badRequest("invalid version");
145	  const missing = await assertVersionsExist(ctx, input);
146	  if (missing !== null) return missing;
147	  return spawnVscodeDiff(
148	    planFilePath(ctx.agentId, ctx.meta, input.from),
149	    planFilePath(ctx.agentId, ctx.meta, input.to)
150	  );
151	};
152	
153	const spawnVscodeDiff = (fromPath: string, toPath: string): Promise<Response> =>
154	  new Promise((resolve) => {
155	    const child = spawn("code", ["--diff", fromPath, toPath], {
156	      detached: true,
157	      stdio: "ignore",
158	    });
159	    child.once("error", (error: NodeJS.ErrnoException) => {
160	      if (error.code === "ENOENT") {
161	        resolve(jsonResponse({ reason: "code-cli-missing" }, 503));
162	        return;
163	      }
164	      resolve(jsonResponse({ reason: "spawn-failed", message: error.message }, 500));
165	    });
166	    child.once("spawn", () => {
167	      child.unref();
168	      resolve(new Response(null, { status: 204 }));
169	    });
170	  });
