172	/**
173	 * Finalize a submission: clear the draft, mark the context resolved so any
174	 * straggling POST /api/draft becomes a no-op, persist the decision for
175	 * out-of-band readers, and resolve the runOneShot promise.
176	 *
177	 * Order matters: clearDraft + markResolved happen BEFORE resolve so that even
178	 * if the runOneShot tear-down (which calls server.stop) runs immediately on
179	 * the next microtask, the draft state is already canonical.
180	 */
181	const finalize = async (ctx: RouteContext, decision: Decision): Promise<void> => {
182	  await clearDraft(ctx.agentId, ctx.meta).catch(() => undefined);
183	  ctx.markResolved();
184	  if (ctx.decisionFile !== undefined && ctx.decisionFile !== null) {
185	    await recordDecision(ctx.decisionFile, decision);
186	  }
187	  ctx.resolve(decision);
188	};
