195	const denyRoute = async (req: Request, ctx: RouteContext): Promise<Response> => {
196	  const body = (await req.json().catch(() => null)) as { feedback?: string } | null;
197	  const feedback = rewriteImageRefs(ctx.agentId, body?.feedback ?? "", ctx.meta);
198	  await finalize(ctx, { kind: "deny", feedback });
