202	const draftGetRoute = async (ctx: RouteContext): Promise<Response> => {
203	  const raw = await loadDraft(ctx.agentId, ctx.meta);
204	  if (raw === null) return new Response(null, { status: 204 });
205	  return new Response(raw, {
206	    status: 200,
207	    headers: { "Content-Type": "application/json; charset=utf-8" },
208	  });
209	};
