211	const draftPostRoute = async (req: Request, ctx: RouteContext): Promise<Response> => {
212	  // After a decision has been resolved, late saves from a queued client-side
213	  // debounce would re-create the draft on disk and resurrect annotations on
214	  // the next session for the same plan slug. Drop them silently.
215	  if (ctx.isResolved()) return new Response(null, { status: 204 });
216	  const raw = await req.text();
217	  await saveDraft(ctx.agentId, ctx.meta, raw);
218	  return new Response(null, { status: 204 });
219	};
