226	const badRequest = (message: string): Response =>
227	  new Response(message, { status: 400, headers: { "Content-Type": "text/plain" } });
228	
229	const uploadRoute = async (req: Request, ctx: RouteContext): Promise<Response> => {
230	  const form = await req.formData().catch(() => null);
231	  const file = form?.get("file");
232	  if (!(file instanceof File)) return badRequest("missing 'file' part");
233	  let extension: string;
234	  try {
235	    extension = assertWhitelistedExtension(file.name);
236	  } catch (error) {
237	    return badRequest(errorMessage(error));
238	  }
239	  const filename = mintUuidFilename(extension);
240	  const target = uploadPath(ctx.agentId, ctx.meta, filename);
241	  try {
242	    assertNoTraversal(agentUploadsRoot(ctx.agentId), target);
243	  } catch (error) {
244	    return badRequest(errorMessage(error));
245	  }
246	  const bytes = await file.arrayBuffer();
247	  await saveUpload(target, bytes);
248	  return jsonResponse({ id: filename.slice(0, -extension.length), extension });
249	};
