251	const mimeByExt: Record<string, string> = {
252	  ".png": "image/png",
253	  ".jpg": "image/jpeg",
254	  ".jpeg": "image/jpeg",
255	  ".gif": "image/gif",
256	  ".webp": "image/webp",
257	};
258	
259	const guessMimeType = (extension: string): string =>
260	  mimeByExt[extension] ?? "application/octet-stream";
261	
262	const resolveImageTarget = (
263	  ctx: RouteContext,
264	  id: string,
265	  extension: string
266	): { target: string } | { error: string } => {
267	  if (!isValidUuid(id)) return { error: "invalid id" };
268	  try {
269	    assertWhitelistedExtension(`x${extension}`);
270	  } catch (error) {
271	    return { error: errorMessage(error) };
272	  }
273	  const target = uploadPath(ctx.agentId, ctx.meta, `${id}${extension}`);
274	  try {
275	    assertNoTraversal(agentUploadsRoot(ctx.agentId), target);
276	  } catch {
277	    return { error: "invalid path" };
278	  }
279	  return { target };
280	};
281	
282	const imageRoute = async (req: Request, ctx: RouteContext): Promise<Response> => {
283	  const url = new URL(req.url);
284	  const id = url.searchParams.get("id") ?? "";
285	  const extension = url.searchParams.get("ext") ?? ".png";
286	  const resolved = resolveImageTarget(ctx, id, extension);
287	  if ("error" in resolved) return badRequest(resolved.error);
288	  const bytes = await loadUpload(resolved.target);
289	  if (bytes === null) return new Response("Not Found", { status: 404 });
290	  // See staticAssets.ts: bun-types' Buffer/Uint8Array don't unify with
291	  // Bun's Response body type across all our tsconfigs. Cast via
292	  // ConstructorParameters avoids the BodyInit name (not always in scope).
293	  // eslint-disable-next-line @typescript-eslint/no-unnecessary-type-assertion
294	  return new Response(bytes as unknown as ConstructorParameters<typeof Response>[0], {
295	    status: 200,
296	    headers: { "Content-Type": guessMimeType(extension) },
297	  });
298	};
299	
300	const imageRefRe = /!\[\]\(([^)]+)\)/g;
301	
302	const tryAbsoluteUploadPath = (agentId: string, meta: PlanMeta, ref: string): string | null => {
303	  const dot = ref.lastIndexOf(".");
304	  if (dot <= 0) return null;
305	  const id = ref.slice(0, dot);
306	  if (!isValidUuid(id)) return null;
307	  try {
308	    assertWhitelistedExtension(ref);
309	  } catch {
310	    return null;
311	  }
312	  const target = uploadPath(agentId, meta, ref);
313	  try {
314	    assertNoTraversal(agentUploadsRoot(agentId), target);
315	  } catch {
316	    return null;
317	  }
318	  return target;
319	};
320	
321	const rewriteImageRefs = (agentId: string, markdown: string, meta: PlanMeta): string =>
322	  markdown.replaceAll(imageRefRe, (match, ref: string) => {
323	    const absolute = tryAbsoluteUploadPath(agentId, meta, ref);
324	    return absolute === null ? match : `![](${absolute})`;
325	  });
326	
327	const feedbackRoute = async (req: Request, ctx: RouteContext): Promise<Response> => {
328	  const body = (await req.json().catch(() => null)) as { feedback?: string } | null;
329	  const feedback = rewriteImageRefs(ctx.agentId, body?.feedback ?? "", ctx.meta);
330	  await saveFeedback(ctx.agentId, ctx.meta, feedback);
331	  await finalize(ctx, { kind: "feedback", feedback });
332	  return new Response(null, { status: 204 });
333	};
334	
335	type Handler = (req: Request, ctx: RouteContext) => Response | Promise<Response>;
336	
337	const routes: Record<string, Handler> = {
338	  [routeKey("plan")]: (_req, ctx) => planRoute(ctx),
339	  [routeKey("planVersions")]: (_req, ctx) => planVersionsRoute(ctx),
340	  [routeKey("planVersion")]: (req, ctx) => planVersionRoute(req, ctx),
341	  [routeKey("planVscodeDiff")]: (req, ctx) => planVscodeDiffRoute(req, ctx),
342	  [routeKey("approve")]: (_req, ctx) => approveRoute(ctx),
343	  [routeKey("deny")]: (req, ctx) => denyRoute(req, ctx),
344	  [routeKey("feedback")]: (req, ctx) => feedbackRoute(req, ctx),
345	  [routeKey("draftGet")]: (_req, ctx) => draftGetRoute(ctx),
346	  [routeKey("draftPut")]: (req, ctx) => draftPostRoute(req, ctx),
347	  [routeKey("draftDelete")]: (_req, ctx) => draftDeleteRoute(ctx),
348	  [routeKey("upload")]: (req, ctx) => uploadRoute(req, ctx),
349	  [routeKey("image")]: (req, ctx) => imageRoute(req, ctx),
350	};
351	
352	export type { RouteContext };
