354	/**
355	 * Dispatch /api/* routes. Returns null for non-API requests so the caller can
356	 * fall through to static-asset serving.
357	 */
358	export const handleApi = async (
359	  req: Request,
360	  url: URL,
361	  ctx: RouteContext
362	): Promise<Response | null> => {
363	  const handler = routes[`${req.method} ${url.pathname}`];
364	  if (handler !== undefined) return handler(req, ctx);
365	  if (url.pathname.startsWith("/api/")) return new Response("Not Found", { status: 404 });
366	  return null;
367	};
