22	// The Plate editor and its diff variant are the heaviest client modules
23	// (platejs + slate + the markdown stack). Loading them lazily lets the shell —
24	// topbar, sidebar, skeleton — paint before Plate is constructed, moving that
25	// work off first paint (TBT/TTI). Under the multi-chunk build (single-file
26	// disabled) these `import()`s also become separate chunks the browser fetches
27	// after the shell. Named-export modules are adapted to React.lazy's default
28	// contract here rather than adding default exports.
29	const EditorMount = lazy(() =>
30	  import("./EditorMount.tsx").then((m) => ({ default: m.EditorMount }))
31	);
32	const DiffMount = lazy(() => import("./DiffMount.tsx").then((m) => ({ default: m.DiffMount })));
33	
34	/** Top-level props for the plan-review surface. */
35	interface ReviewScreenProps {
36	  /** Boot-version plan markdown + viewer mode + meta. */
37	  plan: PlanResponse;
38	  /** Draft loaded by `useDraft`, or `null` if none existed for this slug. */
39	  draft: DraftPayload | null;
40	  /** Debounced auto-save hook from `useDraft`. */
41	  saveDraft: Parameters<typeof useReviewState>[0]["saveDraft"];
42	  /** Cancels in-flight debounced saves before the explicit submission DELETE. */
43	  cancelDraft: () => void;
44	}
45	
46	/** Internal pane selector: switches between editable editor and read-only diff overlay. */
47	interface EditorPaneProps {
48	  isHistorical: boolean;
49	  inCompareOverlay: boolean;
50	  version: ReturnType<typeof useVersionState>;
51	  state: ReturnType<typeof useReviewState>;
52	  plan: PlanResponse;
53	  activePlan: PlanResponse;
54	  onComposerOpenChange: (open: boolean) => void;
55	}
56	
57	/** Derived flags driving sidebar toggle visibility + diff-overlay routing. */
58	interface ReviewFlags {
59	  /** True while the reviewer is browsing a version other than the boot version. */
60	  isHistorical: boolean;
61	  /** True while the boot-version diff overlay (current vs predecessor) is on. */
62	  inCompareOverlay: boolean;
63	  /** True when the visible pane is a diff (either historical or compare-overlay). */
64	  inDiffMode: boolean;
65	  /** True when the boot version exposes a "Compare with predecessor" toggle. */
66	  canCompareWithPredecessor: boolean;
67	}
