69	const deriveReviewFlags = (
70	  version: ReturnType<typeof useVersionState>,
71	  bootVersion: number
72	): ReviewFlags => {
73	  const isHistorical = version.activeVersion !== bootVersion;
74	  const onBoot = !isHistorical;
75	  const hasPredecessor = version.previousVersion !== null;
76	  const canCompareWithPredecessor = onBoot && hasPredecessor;
77	  const inCompareOverlay = canCompareWithPredecessor && version.compareWithPredecessor;
78	  const showsDiff = isHistorical || inCompareOverlay;
79	  const inDiffMode = showsDiff && version.previousPlan !== null;
80	  return { isHistorical, inCompareOverlay, inDiffMode, canCompareWithPredecessor };
81	};
82	
83	const anyOpen = (...flags: boolean[]): boolean => flags.some((f) => f);
84	
85	const HistoricalPlaceholder = (): React.ReactElement => (
86	  <div
87	    data-testid="historical-loading"
88	    className="text-muted-foreground prose prose-neutral dark:prose-invert mx-auto max-w-3xl text-sm"
89	  >
90	    Loading version diff…
91	  </div>
92	);
93	
94	/** Props for the read-only diff overlay rendered on historical or compare-mode selections. */
95	interface DiffOverlayProps {
96	  version: ReturnType<typeof useVersionState>;
97	}
98	
99	// Historical selection: never mount the editable `EditorMount`. Render the
100	// read-only `DiffEditor` (which surfaces an empty-state banner when there is
101	// no predecessor) or a loading placeholder while `previousPlan` is in flight.
102	// Mounting `EditorMount` here would let its `onChange` persist the historical
103	// markdown into the boot-slug's draft.
104	//
105	// `inCompareOverlay` lifts the same diff render onto the boot version so
106	// reviewers can see "what changed in this revision" without remounting
107	// against an older boot.
108	const DiffOverlay = ({ version }: DiffOverlayProps): React.ReactElement => {
109	  if (version.previousPlan === null && version.previousVersion !== null) {
110	    return <HistoricalPlaceholder />;
111	  }
112	  return (
113	    <DiffMount
114	      current={version.activePlan}
115	      previous={version.previousPlan ?? version.activePlan}
116	      currentVersion={version.activeVersion}
117	      previousVersion={version.previousVersion}
118	      mode={version.diffMode}
119	    />
120	  );
121	};
122	
123	const EditorPane = ({
124	  isHistorical,
125	  inCompareOverlay,
126	  version,
127	  state,
128	  plan,
129	  activePlan,
130	  onComposerOpenChange,
131	}: EditorPaneProps): React.ReactElement => {
132	  if (isHistorical || inCompareOverlay) return <DiffOverlay version={version} />;
133	  return (
134	    <EditorMount
135	      reloadKey={state.reloadKey}
136	      activeVersion={version.activeVersion}
137	      bootVersion={plan.meta.version}
138	      plan={activePlan}
139	      initialValue={state.initialValue}
140	      initialBodies={state.initialBodies}
141	      initialImages={state.initialImages}
142	      initialCommentOriginalTexts={state.initialCommentOriginalTexts}
143	      initialSuggestionOriginalTexts={state.initialSuggestionOriginalTexts}
144	      initialInsertionNewTexts={state.initialInsertionNewTexts}
145	      initialInsertionImages={state.initialInsertionImages}
146	      initialInsertionOriginalTexts={state.initialInsertionOriginalTexts}
147	      initialReplacementTexts={state.initialReplacementTexts}
148	      initialReplacementImages={state.initialReplacementImages}
149	      initialReplacementOriginalTexts={state.initialReplacementOriginalTexts}
150	      onReady={state.setEditorHandle}
151	      onChange={state.onEditorChange}
152	      onComposerOpenChange={onComposerOpenChange}
153	    />
154	  );
155	};
