157	/** Composes the topbar, editor, and annotation sidebar; renders `<SubmittedScreen>` once submitted. */
158	export const ReviewScreen = ({
159	  plan,
160	  draft,
161	  saveDraft,
162	  cancelDraft,
163	}: ReviewScreenProps): React.ReactElement => {
164	  const state = useReviewState({ draft, saveDraft });
165	  const edit = useReviewEdit(state);
166	  const version = useVersionState(plan);
167	  // Mirror the TopBar context + plan H1 in the browser tab. Boot `plan.plan` per
168	  // issue #148 scope; pass `version.activePlan` to instead track the on-screen version.
169	  useDocumentTitle(plan.meta.displayName, plan.plan);
170	  const { phase, onApprove, onSubmit } = useReviewSubmit({
171	    planMode: plan.mode,
172	    editorHandle: state.editorHandle,
173	    collectEntries: state.collectEntries,
174	    cancelDraft,
175	  });
176	  const [globalCommentOpen, setGlobalCommentOpen] = useState(false);
177	  const [inlineComposerOpen, setInlineComposerOpen] = useState(false);
178	  const onOpenGlobalComment = useCallback((): void => setGlobalCommentOpen(true), []);
179	  const composerOpen = anyOpen(globalCommentOpen, inlineComposerOpen, edit.editing !== null);
180	
181	  const flags = deriveReviewFlags(version, plan.meta.version);
182	  const { isHistorical, inCompareOverlay, inDiffMode, canCompareWithPredecessor } = flags;
183	  const hasAnnotations = state.sidebarEntries.length > 0;
184	
185	  useReviewHotkeys({
186	    phase,
187	    mode: plan.mode,
188	    hasAnnotations,
189	    inReadOnlyView: isHistorical || inCompareOverlay,
190	    composerOpen,
191	    editorHandle: state.editorHandle,
192	    onApprove,
193	    onSubmit,
194	    onOpenGlobalComment,
195	  });
196	
197	  if (phase === "done") return <SubmittedScreen mode={plan.mode} />;
198	
199	  const activePlan: PlanResponse = {
200	    ...plan,
201	    plan: version.activePlan,
202	    meta: { ...plan.meta, version: version.activeVersion },
203	  };
204	
205	  return (
206	    <SidebarProvider defaultOpen style={{ "--sidebar-width": "20rem" } as CSSProperties}>
207	      <SidebarInset className="flex h-svh flex-col">
208	        <TopBar
209	          onApprove={onApprove}
210	          onDeny={onSubmit}
211	          projectName={plan.meta.displayName}
212	          busy={phase === "submitting"}
213	          mode={plan.mode}
214	          hasAnnotations={hasAnnotations}
215	        />
216	        <div className="flex-1 overflow-auto p-15">
217	          <EditorErrorBoundary>
218	            <Suspense fallback={<LoadingFallback label="Loading editor…" />}>
219	              <EditorPane
220	                isHistorical={isHistorical}
221	                inCompareOverlay={inCompareOverlay}
222	                version={version}
223	                state={state}
224	                plan={plan}
225	                activePlan={activePlan}
226	                onComposerOpenChange={setInlineComposerOpen}
227	              />
228	            </Suspense>
229	          </EditorErrorBoundary>
230	        </div>
231	        {!isHistorical && !inCompareOverlay && (
232	          <GlobalCommentFab
233	            onAddGlobalComment={state.onAddGlobalComment}
234	            disabled={phase === "submitting"}
235	            open={globalCommentOpen}
236	            onOpenChange={setGlobalCommentOpen}
237	          />
238	        )}
239	      </SidebarInset>
240	      <EditAnnotationComposer
241	        editing={edit.editing}
242	        onSave={edit.onSave}
243	        onCancel={edit.onCancel}
244	      />
245	      <AnnotationSidebar
246	        entries={state.sidebarEntries}
247	        onFocus={focusAnnotation}
248	        onRemove={state.onRemoveAnnotation}
249	        onEdit={edit.onEdit}
250	        onClearAll={state.onClearAll}
251	        versions={version.versions}
252	        activeVersion={version.activeVersion}
253	        onSelectVersion={version.onSelectVersion}
254	        showDiffToggle={inDiffMode}
255	        diffMode={version.diffMode}
256	        onDiffModeChange={version.onDiffModeChange}
257	        canCompareWithPredecessor={canCompareWithPredecessor}
258	        comparingWithPredecessor={version.compareWithPredecessor}
259	        onToggleCompare={version.onToggleCompare}
260	      />
261	    </SidebarProvider>
262	  );
263	};
