1	import { useCallback, useEffect, useRef, useState } from "react";
2	
3	import { type DraftPayload } from "../../shared/apiTypes.ts";
4	import { getDraft, putDraft } from "../libs/apiClient.ts";
5	
6	import { useCancelledFetch } from "./useCancelledFetch.ts";
7	
8	/** Captured editor state passed in on each change. */
9	export interface DraftSnapshot {
10	  value: unknown[];
11	  commentBodies: Map<string, string>;
12	  commentImages: Map<string, string[]>;
13	  commentOriginalTexts: Map<string, string>;
14	  suggestionOriginalTexts: Map<string, string>;
15	  insertionNewTexts: Map<string, string>;
16	  insertionImages: Map<string, string[]>;
17	  insertionOriginalTexts: Map<string, string>;
18	  replacementTexts: Map<string, string>;
19	  replacementImages: Map<string, string[]>;
20	  replacementOriginalTexts: Map<string, string>;
21	  globalComments: { id: string; body: string; images?: string[] }[];
22	}
23	
24	interface DraftHook {
25	  /** The draft loaded on mount, or null if none existed / still loading. */
26	  loaded: DraftPayload | null;
27	  /** True until the first GET /api/draft resolves. */
28	  isLoading: boolean;
29	  /** Debounced auto-save call — pass the latest editor snapshot on every change. */
30	  save: (snapshot: DraftSnapshot) => void;
31	  /**
32	   * Cancel any pending debounced save AND disable future `save` calls.
33	   * Call this at the start of submission so a queued POST doesn't fire after
34	   * the explicit DELETE and re-create the draft on disk.
35	   */
36	  cancel: () => void;
37	}
38	
39	const toPayload = (snapshot: DraftSnapshot): DraftPayload => ({
40	  value: snapshot.value,
41	  commentBodies: Object.fromEntries(snapshot.commentBodies),
42	  commentImages: Object.fromEntries(snapshot.commentImages),
43	  commentOriginalTexts: Object.fromEntries(snapshot.commentOriginalTexts),
44	  suggestionOriginalTexts: Object.fromEntries(snapshot.suggestionOriginalTexts),
45	  insertionNewTexts: Object.fromEntries(snapshot.insertionNewTexts),
46	  insertionImages: Object.fromEntries(snapshot.insertionImages),
47	  insertionOriginalTexts: Object.fromEntries(snapshot.insertionOriginalTexts),
48	  replacementTexts: Object.fromEntries(snapshot.replacementTexts),
49	  replacementImages: Object.fromEntries(snapshot.replacementImages),
50	  replacementOriginalTexts: Object.fromEntries(snapshot.replacementOriginalTexts),
51	  globalComments: snapshot.globalComments,
52	  updatedAt: Date.now(),
53	});
54	
55	const debounceMs = 1_000;
56	
57	/**
58	 * Auto-save the reviewer's in-progress annotations to the server so they
59	 * survive page reloads. Loads any existing draft on mount; debounces save
60	 * calls by 1s; the caller invokes DELETE explicitly on submit.
61	 */
62	export const useDraft = (): DraftHook => {
63	  const [loaded, setLoaded] = useState<DraftPayload | null>(null);
64	  const [isLoading, setIsLoading] = useState(true);
65	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
66	  const disabledRef = useRef(false);
67	
68	  useCancelledFetch(
69	    getDraft,
70	    (draft) => {
71	      setLoaded(draft);
72	      setIsLoading(false);
73	    },
74	    (error) => {
75	      console.error("failed to load draft", error);
76	      setIsLoading(false);
77	    },
78	    []
79	  );
80	
81	  const save = useCallback((snapshot: DraftSnapshot): void => {
82	    if (disabledRef.current) return;
83	    if (timerRef.current !== null) clearTimeout(timerRef.current);
84	    timerRef.current = setTimeout(() => {
85	      if (disabledRef.current) return;
86	      void putDraft(toPayload(snapshot)).catch((error: unknown) => {
87	        console.error("failed to save draft", error);
88	      });
89	    }, debounceMs);
90	  }, []);
91	
92	  const cancel = useCallback((): void => {
93	    disabledRef.current = true;
94	    if (timerRef.current !== null) {
95	      clearTimeout(timerRef.current);
96	      timerRef.current = null;
97	    }
98	  }, []);
99	
100	  useEffect(
101	    () => () => {
102	      if (timerRef.current !== null) clearTimeout(timerRef.current);
103	    },
104	    []
105	  );
106	
107	  return { loaded, isLoading, save, cancel };
108	};
