1	import { useCallback, useState } from "react";
2	import { serializeFeedback, type AnnotationEntry } from "@symbiot/annotations";
3	import { type ReviewEditorHandle } from "@symbiot/editor/components/ReviewEditor";
4	
5	import { type ViewerMode } from "../../shared/apiTypes.ts";
6	import { deleteDraft, postApprove, postDeny, postFeedback } from "../libs/apiClient.ts";
7	
8	/** Submission lifecycle phase: ready → submitting → done. */
9	export type Phase = "ready" | "submitting" | "done";
10	
11	/** Inputs the submission hook needs from the surrounding review session. */
12	export interface ReviewSubmitProps {
13	  planMode: ViewerMode;
14	  editorHandle: ReviewEditorHandle | null;
15	  collectEntries: () => AnnotationEntry[];
16	  /** Stop the auto-save loop *before* the explicit DELETE so a queued POST can't resurrect the draft. */
17	  cancelDraft: () => void;
18	}
19	
20	/** Phase signal + the two submission callbacks the `<TopBar>` wires up. */
21	export interface ReviewSubmit {
22	  phase: Phase;
23	  onApprove: () => Promise<void>;
24	  onSubmit: () => Promise<void>;
25	}
26	
27	/**
28	 * Owns the side-effecting submission flow (approve / deny / feedback) and the
29	 * `phase` lifecycle that gates the UI. Sequence is always:
30	 * `cancelDraft → POST decision → DELETE draft → setPhase("done") → window.close`.
31	 */
32	export const useReviewSubmit = ({
33	  planMode,
34	  editorHandle,
35	  collectEntries,
36	  cancelDraft,
37	}: ReviewSubmitProps): ReviewSubmit => {
38	  const [phase, setPhase] = useState<Phase>("ready");
39	
40	  const onApprove = useCallback(async () => {
41	    setPhase("submitting");
42	    // Stop the auto-save loop FIRST: a queued POST /api/draft fired after the
43	    // DELETE below would re-create the draft and resurrect annotations on the
44	    // next plan-review session for the same slug.
45	    cancelDraft();
46	    await postApprove();
47	    await deleteDraft().catch(() => undefined);
48	    setPhase("done");
49	    window.close();
50	  }, [cancelDraft]);
51	
52	  const onSubmit = useCallback(async () => {
53	    if (editorHandle === null) return;
54	    setPhase("submitting");
55	    cancelDraft();
56	    const feedback = serializeFeedback(collectEntries());
57	    const submit = planMode === "annotate" ? postFeedback : postDeny;
58	    await submit(feedback);
59	    await deleteDraft().catch(() => undefined);
60	    setPhase("done");
61	    window.close();
62	  }, [cancelDraft, collectEntries, editorHandle, planMode]);
63	
64	  return { phase, onApprove, onSubmit };
65	};
