1	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
2	import type { DiffMode } from "@symbiot/editor/components/DiffEditor";
3	
4	import { fetchPlanVersion, fetchPlanVersions } from "../libs/apiClient.ts";
5	import type { PlanResponse, PlanVersionResponse } from "../../shared/apiTypes.ts";
6	
7	import { useCancelledFetch } from "./useCancelledFetch.ts";
8	
9	const diffModeStorageKey = "symbiot.diffMode";
10	
11	const readDiffMode = (): DiffMode => {
12	  if (typeof window === "undefined") return "clean";
13	  const raw = window.localStorage.getItem(diffModeStorageKey);
14	  return raw === "raw" ? "raw" : "clean";
15	};
16	
17	const writeDiffMode = (mode: DiffMode): void => {
18	  if (typeof window === "undefined") return;
19	  window.localStorage.setItem(diffModeStorageKey, mode);
20	};
21	
22	/** Slice of state powering the History tab in the sidebar. */
23	export interface VersionState {
24	  /** Ascending list of every version persisted under the plan's history dir. */
25	  versions: number[];
26	  /** The version number currently rendered in the editor. */
27	  activeVersion: number;
28	  /** Markdown for the currently rendered version (overrides `plan.plan` after a switch). */
29	  activePlan: string;
30	  /** Version number immediately preceding `activeVersion`. `null` when none exists. */
31	  previousVersion: number | null;
32	  /** Markdown for the version immediately preceding `activeVersion`. `null` when none exists. */
33	  previousPlan: string | null;
34	  /** Diff render mode for the History tab toggle. Persisted per browser. */
35	  diffMode: DiffMode;
36	  /**
37	   * When true AND the reviewer is on the boot version with a predecessor
38	   * available, the editor pane renders a read-only diff overlay (current vs
39	   * predecessor) instead of the editable editor. Auto-resets on version
40	   * switch so a stale `true` can't bleed across selections.
41	   */
42	  compareWithPredecessor: boolean;
43	  /** Switch the editor to a previously persisted version. */
44	  onSelectVersion: (version: number) => void;
45	  /** Update the Clean/Raw toggle for diff rendering. */
46	  onDiffModeChange: (mode: DiffMode) => void;
47	  /** Flip the "compare current with predecessor" overlay on the boot version. */
48	  onToggleCompare: () => void;
49	}
50	
51	const findPredecessorInIndex = (
52	  versions: number[],
53	  index: Map<number, number>,
54	  active: number
55	): number | null => {
56	  const idx = index.get(active);
57	  if (idx === undefined || idx <= 0) return null;
58	  return versions[idx - 1] ?? null;
59	};
60	
61	/**
62	 * Loads the on-disk version history for the active plan and lets the reviewer
63	 * switch which version the editor renders. The initial `activePlan` mirrors
64	 * the markdown the server boot-loaded; subsequent switches go through
65	 * `GET /api/plan/version?n=N`. `previousPlan` is fetched lazily whenever
66	 * `activeVersion` changes so the diff editor has both sides available.
67	 *
68	 */
69	export const useVersionState = (plan: PlanResponse): VersionState => {
70	  const [versions, setVersions] = useState<number[]>([plan.meta.version]);
71	  const [activeVersion, setActiveVersion] = useState<number>(plan.meta.version);
72	  const [activePlan, setActivePlan] = useState<string>(plan.plan);
73	  const [previousFetched, setPreviousFetched] = useState<{
74	    version: number;
75	    plan: string;
76	  } | null>(null);
77	  const [diffMode, setDiffMode] = useState<DiffMode>(readDiffMode);
78	  const [compareWithPredecessor, setCompareWithPredecessor] = useState(false);
79	
80	  useCancelledFetch(
81	    fetchPlanVersions,
82	    (res) => setVersions(res.versions.length > 0 ? res.versions : [plan.meta.version]),
83	    null,
84	    [plan.meta.version]
85	  );
86	
87	  const latestActiveRequestRef = useRef(0);
88	  const latestPreviousRequestRef = useRef(0);
89	
90	  const versionIndex = useMemo(
91	    () => new Map(versions.map((value, index) => [value, index])),
92	    [versions]
93	  );
94	
95	  const previousVersion = useMemo(
96	    () => findPredecessorInIndex(versions, versionIndex, activeVersion),
97	    [versions, versionIndex, activeVersion]
98	  );
99	
100	  useEffect(() => {
101	    if (previousVersion === null) return;
102	    latestPreviousRequestRef.current += 1;
103	    const requestId = latestPreviousRequestRef.current;
104	    fetchPlanVersion(previousVersion)
105	      .then((res: PlanVersionResponse) => {
106	        if (requestId !== latestPreviousRequestRef.current) return;
107	        setPreviousFetched({ version: previousVersion, plan: res.plan });
108	      })
109	      .catch(() => undefined);
110	  }, [previousVersion]);
111	
112	  // Derived: only surface `previousPlan` when the fetched markdown matches
113	  // the current predecessor. Avoids a synchronous setState-in-effect when
114	  // the active version has no predecessor (the smallest version on disk).
115	  const previousPlan =
116	    previousVersion !== null && previousFetched?.version === previousVersion
117	      ? previousFetched.plan
118	      : null;
119	
120	  const onSelectVersion = useCallback(
121	    (version: number): void => {
122	      if (version === activeVersion) return;
123	      // Switching off the boot version implicitly exits the predecessor-diff
124	      // overlay so the new selection's natural Historical / Editable rendering
125	      // takes over.
126	      setCompareWithPredecessor(false);
127	      latestActiveRequestRef.current += 1;
128	      const requestId = latestActiveRequestRef.current;
129	      fetchPlanVersion(version)
130	        .then((res) => {
131	          if (requestId !== latestActiveRequestRef.current) return;
132	          setActivePlan(res.plan);
133	          setActiveVersion(res.meta.version);
134	        })
135	        .catch(() => undefined);
