/**
 * Draft-mode autosave: persists the typed markdown via `/api/draft` so an
 * accidental tab close within a live session loses nothing.
 *
 * Hydration precedence: the payload is applied only when its `version` equals
 * the boot version. Every viewer boot bumps the version, so a stale blob from
 * a crashed prior run can never mask the fresh CLI seed — across runs the CLI
 * file always wins; within a session a reload restores the typed text.
 */
import { useCallback, useEffect, useRef, useState } from "react";

import { getDraftBody, putDraftBody } from "../libs/apiClient.ts";

import { useCancelledFetch } from "./useCancelledFetch.ts";

/** Surface returned by {@link useDraftBody}. */
export interface DraftBodyHook {
  /** Autosaved markdown for THIS boot version, or null when none applies. */
  loaded: string | null;
  /** True until the first `GET /api/draft` resolves. */
  isLoading: boolean;
  /**
   * Debounced auto-save — pass a lazy getter so serialization runs once per
   * flush, not on every keystroke.
   */
  save: (getMarkdown: () => string) => void;
  /** Cancel any pending debounced save AND disable future saves (call at submit start). */
  cancel: () => void;
}

const debounceMs = 1_000;

export const useDraftBody = (bootVersion: number): DraftBodyHook => {
  const [loaded, setLoaded] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const disabledRef = useRef(false);

  useCancelledFetch(
    getDraftBody,
    (payload) => {
      setLoaded(payload !== null && payload.version === bootVersion ? payload.markdown : null);
      setIsLoading(false);
    },
    (error) => {
      console.error("failed to load draft body", error);
      setIsLoading(false);
    },
    []
  );

  const save = useCallback(
    (getMarkdown: () => string): void => {
      if (disabledRef.current) return;
      if (timerRef.current !== null) clearTimeout(timerRef.current);
      timerRef.current = setTimeout(() => {
        if (disabledRef.current) return;
        void putDraftBody({
          markdown: getMarkdown(),
          version: bootVersion,
          updatedAt: Date.now(),
        }).catch((error: unknown) => {
          console.error("failed to save draft body", error);
        });
      }, debounceMs);
    },
    [bootVersion]
  );

  const cancel = useCallback((): void => {
    disabledRef.current = true;
    if (timerRef.current !== null) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  useEffect(
    () => () => {
      if (timerRef.current !== null) clearTimeout(timerRef.current);
    },
    []
  );

  return { loaded, isLoading, save, cancel };
};

/**
 * Draft-mode submission flow: "Send to agent" persists the edited body as the
 * next version and resolves the session with a `draft` decision; "Approve"
 * persists it and resolves `approve` — both serialize the Plate value to
 * markdown once, at submit time. Sequence mirrors the review submit hook:
 * `cancelDraft → POST decision → DELETE draft → phase "done" → window.close`.
 */
import { useCallback, useState } from "react";
import { type DraftEditorHandle } from "@symbiot/editor/components/DraftEditor";

import { deleteDraft, postApprove, postDraftSend } from "../libs/apiClient.ts";

import { type Phase } from "./useReviewSubmit.ts";

/** Which draft outcome was submitted — drives the confirmation heading. */
export type DraftOutcome = "sent" | "approved";

/** Inputs the draft submission hook needs from the surrounding session. */
export interface DraftSubmitProps {
  editorHandle: DraftEditorHandle | null;
  /** Stop the auto-save loop *before* the explicit DELETE so a queued POST can't resurrect the draft. */
  cancelDraft: () => void;
}

/** Phase signal, submitted outcome, and the two actions the `<TopBar>` wires up. */
export interface DraftSubmit {
  phase: Phase;
  outcome: DraftOutcome;
  onSend: () => Promise<void>;
  onApprove: () => Promise<void>;
}

export const useDraftSubmit = ({ editorHandle, cancelDraft }: DraftSubmitProps): DraftSubmit => {
  const [phase, setPhase] = useState<Phase>("ready");
  const [outcome, setOutcome] = useState<DraftOutcome>("sent");

  const submit = useCallback(
    async (kind: DraftOutcome): Promise<void> => {
      if (editorHandle === null) return;
      setPhase("submitting");
      cancelDraft();
      const markdown = editorHandle.getMarkdown();
      await (kind === "sent" ? postDraftSend(markdown) : postApprove(markdown));
      await deleteDraft().catch(() => undefined);
      setOutcome(kind);
      setPhase("done");
      window.close();
    },
    [cancelDraft, editorHandle]
  );

  const onSend = useCallback(() => submit("sent"), [submit]);
  const onApprove = useCallback(() => submit("approved"), [submit]);

  return { phase, outcome, onSend, onApprove };
};

